        content:
          "식약처 허가사항이 명시한 효능효과는 \"위산과다, 속쓰림, 위부불쾌감, 위부팽만감, 체함, 구역, 구토, 위통, 신트림, 식욕감퇴(식욕부진), 소화불량, 과식\" 12개예요. e약은요 표기를 그대로 옮긴 거예요. 겔포스엠 9개와 비교하면 식욕감퇴·소화불량·과식 3개가 추가돼 있어요.\n\n작용은 두 갈래로 갈려요. 첫째, 인산알루미늄겔과 수산화마그네슘이 위산을 직접 중화하고 시메티콘이 가스 거품을 분쇄해 \"속쓰림·체함·구역·구토\" 같은 일반 제산제 적응증을 커버해요. 둘째, DL-카르니틴염산염이 위장 운동성을 개선해 \"식욕감퇴·소화불량·과식\" 적응증을 추가로 책임져요.\n\n그래서 겔포스엘이 어울리는 분은 명확해요. 단순 속쓰림보다 \"먹어도 식욕이 안 돌아오고 과식 후 안 내려가는\" 패턴이 같이 있는 경우예요. 단순 위산 중화·가스 제거가 핵심이라면 겔포스엠이 인산알루미늄겔이 5배 많아 더 강한 중화력을 가져요. \"식욕\"과 \"소화\"가 키워드라면 겔포스엘이 맞아요.",
