        content:
          "식약처 허가사항이 명시한 효능효과는 \"산 역류, 속쓰림, 위 내용물의 역류로 인한 소화불량(예를 들어 식사 후, 임신 중, 역류성 식도염과 동반하는 경우)\"이에요. e약은요 표기를 그대로 옮긴 거고, 개비스콘더블액션과 완전히 동일한 적응증이에요.\n\n작용은 두 갈래(이중 작용)예요. 첫째, 알긴산 raft가 위 내용물·위산이 식도로 역류하는 걸 물리적으로 막아요. 식도 점막에 위산이 직접 닿지 않으니 역류성 식도염의 \"가슴 타는 통증\"이 빠르게 줄어요. 둘째, 탄산칼슘·탄산수소나트륨이 위산을 중화해 일반 제산 효과를 더해요.\n\n적응증에 \"임신 중\" 역류가 명시된 게 특징이에요. 임신 후반기에 자궁이 위를 압박해 생기는 역류성 식도염은 흔하고, 알긴산은 위장에서 흡수되지 않아 임부에게 비교적 안전한 옵션으로 알려져 있어요. 노루모듀얼액션이 어울리는 분은 \"개비스콘과 같은 알긴산 처방을 국산 제품으로 찾는\" 분, \"4포·10포 같은 작은 단위로 시도해보고 싶은\" 분이에요. 단순 속쓰림보다 \"역류·신트림·가슴 타는 느낌\"이 핵심일 때 어울려요.",
