          "허가사항 용법용량은 \"만 15세 이상은 1회 2정씩, 1일 3회 복용\"이에요. 1일 6정이 풀 용량이에요. 만 7세 이하 어린이는 절대 금기예요. 만 8~14세는 자가 복용 대상이 아니라 의사·약사 상담이 필요해요.\n\n복용 타이밍은 식간이나 증상이 있을 때 자유롭게 복용할 수 있어요. \"식간\"이나 \"식후\" 같은 명시 타이밍은 허가사항에 적혀 있지 않아요. 정제는 통째로 삼키거나 씹어서 복용해도 돼요(허가사항에 별도 표기 없음). 코팅정이라 쓴맛은 적지만 씹으면 코팅이 부서져 약효 발현은 약간 느릴 수 있어요.\n\n2주 정도 복용해도 증상의 개선이 없으면 복용을 중지하고 의사·약사와 상의해야 해요. 다른 경구약과는 1~2시간 간격을 두는 게 안전해요. 1일 6정 풀 용량을 매일 채우는 분이라면 박스가 빠르게 소진되니 단발성 사용이 권장돼요.",
