    description:
      "바로스콘더블15(영진약품 2014 허가) 식약처 등록 알긴산나트륨+탄산칼슘+탄산수소나트륨 3성분, 12세 이상 1회 10~20mL 1일 4회 식후·취침 ",
    heroDescription:
      "15mL 큰 용량 1포로 1주일 평가 분량을 사두려는 분께 어울리는 게 바로스콘더블15예요. 영진약품(주) 2014년 2월 26일 허가, 식약처 품목번호 201400876이에요. 알긴산나트륨이 위 내용물 위에 젤 층을 만들어 역류를 차단하는 알긴산 raft 처방이에요.",
    products: [],
